import { generateCanalCity } from './canalCity.js';
import { generateAutumnValley } from './autumnValley.js';
import { generateCherryShrine } from './cherryShrine.js';
import { generateMoonGarden } from './moonGarden.js';
import { generatePineRetreat } from './pineRetreat.js';
import { polishNature } from './naturePolish.js';
import { generateSkyGarden } from './skyGarden.js';
import { generateCoralIslands } from './coralIslands.js';
import { generateDesertOasis } from './desertOasis.js';
import { generateBambooOnsen } from './bambooOnsen.js';
import { addLivingWorld } from './livingWorld.js';
import { EXPANSION_IDS } from './expansionCatalog.js';
import { generateThemedTerrain } from './themedTerrain.js';
import { mapConfig, mapLimit } from './mapConfig.js';
import { addLandmarks } from './landmarks.js';
import { scenicHeight } from './scenicTerrain.js';
import { addScenicFeatures } from './scenicFeatures.js';
export const TERRAIN_VERSION = 1;
export const WATER_LEVEL = 2.8;
export function hashSeed(text) {
  let h = 2166136261;
  for (const c of String(text)) h = Math.imul(h ^ c.charCodeAt(0), 16777619);
  return h >>> 0;
}
export function randomAt(seed, x, z) {
  let h = Math.imul(x ^ seed, 374761393) ^ Math.imul(z, 668265263);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}
export function generateTerrain(seed = 'willow', options = {}) {
  const config=mapConfig(options),limit=mapLimit(config),kind=config.mapType;
  if(config.generator===4){
    if(kind==='canal')return addLivingWorld(generateCanalCity(seed,config,hashSeed(seed)));
    if(kind==='autumn')return addLivingWorld(generateAutumnValley(seed,config,hashSeed(seed)));
    if(kind==='shrine')return addLivingWorld(generateCherryShrine(seed,config,hashSeed(seed)));
    if(kind==='moon')return addLivingWorld(generateMoonGarden(seed,config,hashSeed(seed)));
    if(kind==='pine')return addLivingWorld(generatePineRetreat(seed,config,hashSeed(seed)));
    if(['forest','meadow','islands','snow'].includes(kind))return polishNature(generateTerrain(seed,{...config,generator:3}),hashSeed(seed));
    if(kind==='sky')return addLivingWorld(generateSkyGarden(seed,config,hashSeed(seed)));
    if(kind==='coral')return addLivingWorld(generateCoralIslands(seed,config,hashSeed(seed)));
    if(kind==='oasis')return addLivingWorld(generateDesertOasis(seed,config,hashSeed(seed)));
    if(kind==='onsen')return addLivingWorld(generateBambooOnsen(seed,config,hashSeed(seed)));
    return {...generateTerrain(seed,{...config,generator:3}),generator:4};
  }
  if(config.generator===3)return addLivingWorld({...generateTerrain(seed,{...config,generator:2}),generator:3});
  if(EXPANSION_IDS.includes(kind))return generateThemedTerrain(seed,config,hashSeed(seed));
  const salt = hashSeed(seed), cubes = [], heights = new Map(), water = [], flowers = [], occupied = new Set();
  const phase = (salt % 1000) / 157;
  const add = (x,y,z,texture) => {
    const key=[x,y,z].join(',');
    if(occupied.has(key))return;
    occupied.add(key);cubes.push({key,pos:[x,y,z],texture});
  };
  for (let x=-limit;x<=limit;x++) for(let z=-limit;z<=limit;z++) {
    const coast = 30 + 3 * Math.sin(z / 12 + phase);
    const lake = Math.hypot((x+18)/1.15,z+13);
    let height = Math.round(5 + 2*Math.sin(x/15+phase)*Math.sin(z/17) + 3*Math.exp(-((x+27)**2+(z+34)**2)/260));
    if (x>coast-7) height = Math.min(height, Math.max(1, Math.round((coast-x)/3+2)));
    if (lake<12) height = Math.min(height, Math.max(1,Math.round((lake-6)/2+1)));
    if(kind==='meadow')height=Math.round(4.5+Math.sin(x/24+phase)*Math.sin(z/27));
    if(kind==='islands')height=Math.max(1,Math.round(1+5*Math.max(0,Math.sin(x/12+phase)*Math.cos(z/14))));
    if(kind==='snow')height=Math.round(6+3*Math.sin(x/21+phase)*Math.sin(z/23)+2*Math.cos((x+z)/30));
    // Generator 2 is opt-in: old worlds keep their exact terrain and edit baseline.
    let rocky=false;
    if(config.generator===2) {
      height=scenicHeight(kind,x,z,phase,limit);
      rocky=kind==='snow'?height>23:kind==='islands'?height>11:height>15;
    }
    // A broad clearing and two level trails connect the starting point to the biomes.
    const path = Math.min(Math.abs(x),Math.abs(z-10));
    if(config.generator===1 && kind!=='islands' && path<5 && x<28) height = Math.round(height+(5-height)*Math.max(0,1-path/5));
    if(config.generator===2&&Math.hypot(x,z-10)<5)height=5;
    if(config.generator===1 && kind==='islands' && Math.hypot(x,z-10)<7)height=Math.max(height,Math.round(5-Math.hypot(x,z-10)/3));
    heights.set(`${x},${z}`,height);
    for(let y=1;y<=height;y++) add(x,y,z,y===height?(rocky?'stone':kind==='snow'?'snow':height<=3?'sand':'grass'):y<height-2?'stone':'dirt');
    if(height+.5<WATER_LEVEL) water.push([x,WATER_LEVEL,z]);
    if(kind!=='snow' && height>=4 && path>3 && randomAt(salt,x,z)>(config.generator===2&&kind==='meadow'?.92:.975)) flowers.push([x,height+.75,z]);
  }
  // Trees are editable voxels, with empty trails and a clear spawn radius.
  for(let gx=-(limit-5);gx<(kind==='forest'?(config.generator===1?25:limit*.55):limit-4);gx+=5) for(let gz=-(limit-5);gz<limit-4;gz+=5){
    const x=gx+(config.generator===2?Math.floor(randomAt(salt+9,gx,gz)*3)-1:0),z=gz+(config.generator===2?Math.floor(randomAt(salt+8,gx,gz)*3)-1:0);
    const h=heights.get(`${x},${z}`);
    if(config.generator===1 ? (h<4||Math.abs(x)<5||Math.abs(z-10)<5||randomAt(salt,x,z)<(kind==='meadow'?.94:kind==='islands'?.68:.42)) : (h<4||h>23||Math.hypot(x,z-10)<8||randomAt(salt,x,z)<(kind==='meadow'?(.88+.09*Math.sin(x/14)*Math.cos(z/16)):kind==='islands'?.6:kind==='snow'?.62:.32)))continue;
    const trunk=config.generator===1?3+Math.floor(randomAt(salt+1,x,z)*2):(kind==='snow'?6:3)+Math.floor(randomAt(salt+1,x,z)*3);
    for(let y=1;y<=trunk;y++)add(x,h+y,z,'log');
    if(config.generator===2 && kind==='snow'){
      for(let dy=2;dy<=trunk+2;dy++){const r=Math.max(0,Math.ceil((trunk+2-dy)/2));for(let dx=-r;dx<=r;dx++)for(let dz=-r;dz<=r;dz++){if(Math.abs(dx)+Math.abs(dz)>r+1||(!dx&&!dz&&dy<=trunk))continue;add(x+dx,h+dy,z+dz,dy%2===0?'snow':'leaves');}}
      continue;
    }
    for(let dx=-2;dx<=2;dx++)for(let dz=-2;dz<=2;dz++)for(let dy=0;dy<=2;dy++){
      if(Math.abs(dx)+Math.abs(dz)+dy>4 || (dx===0&&dz===0&&dy===0))continue;
      add(x+dx,h+trunk+dy,z+dz,'leaves');
    }
  }
  const terrain={seed:String(seed),...config,cubes,heights,water,flowers};
  return config.generator===2 ? addScenicFeatures(addLandmarks(terrain,salt),salt) : terrain;
}

// Saves contain only edits relative to this version of the deterministic generator.
export function serializeTerrain(seed, base, current, options={}) {
  const edits=[];
  for(const [key,cube] of base)if(!current.has(key))edits.push({pos:cube.pos,texture:null});
  for(const [key,cube] of current)if(base.get(key)?.texture!==cube.texture)edits.push({pos:cube.pos,texture:cube.texture});
  return JSON.stringify({version:2,generator:TERRAIN_VERSION,seed,...mapConfig(options),edits});
}
export function restoreTerrain(raw, seed, cubes, validPosition, types, options={}) {
  const data=JSON.parse(raw);
  if(data.version!==2||![1,2,3,4].includes(data.generator)||data.seed!==seed||!Array.isArray(data.edits))throw Error('Unsupported landscape save');
  const config=mapConfig(options),saved=mapConfig(data);
  if((data.mapType!==undefined && data.mapType!==saved.mapType)||(data.size!==undefined && data.size!==saved.size)||config.mapType!==saved.mapType||config.size!==saved.size||config.generator!==saved.generator)throw Error('Landscape configuration mismatch');
  const blocks=new Map(cubes.map(c=>[c.key,c]));
  for(const edit of data.edits){
    if(!edit||!validPosition(edit.pos)||(edit.texture!==null&&!types.includes(edit.texture)))throw Error('Invalid landscape edit');
    const key=edit.pos.join(',');
    if(edit.texture===null)blocks.delete(key);else blocks.set(key,{key,pos:[...edit.pos],texture:edit.texture});
  }
  return [...blocks.values()];
}
